import{_ as t,o,c as a,b6 as n}from"./chunks/framework.COUcLbTA.js";const h=JSON.parse('{"title":"From Idea to AI Product - Easy-Vibe Learning Roadmap","description":"Complete roadmap for learning AI programming: from zero basics to full-stack development. Master AI IDE tools like Vibe Coding, Claude Code, and Cursor, and learn product thinking, full-stack development, and AI capability integration.","frontmatter":{"title":"From Idea to AI Product - Easy-Vibe Learning Roadmap","description":"Complete roadmap for learning AI programming: from zero basics to full-stack development. Master AI IDE tools like Vibe Coding, Claude Code, and Cursor, and learn product thinking, full-stack development, and AI capability integration."},"headers":[],"relativePath":"en/stage-1/learning-map/index.md","filePath":"en/stage-1/learning-map/index.md"}'),i={name:"en/stage-1/learning-map/index.md"};function r(s,e,l,d,u,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="from-idea-to-ai-product" tabindex="-1">From Idea to AI Product <a class="header-anchor" href="#from-idea-to-ai-product" aria-label="Permalink to “From Idea to AI Product”">​</a></h1><div class="info custom-block"><p class="custom-block-title">Special Thanks</p><p>Special thanks to the students from <strong>Tsinghua University Shenzhen International Graduate School</strong> for their testing, feedback, and support for this course! Your contributions and suggestions have made this course better. <a href="https://github.com/datawhalechina/easy-vibe#-contributing--contributors" target="_blank" rel="noreferrer">👉 View full contributors list</a></p></div><p>In the past, building software had a high barrier: you had to understand programming and algorithms and have years of project experience. Now it&#39;s different. As long as you have an idea, AI can help you write the code.</p><p>This is a huge change: <strong>Programming languages are becoming natural languages</strong>.</p><p>The emergence of Large Language Models (LLMs) has turned development from a &quot;technical expert&#39;s exclusive&quot; into a tool everyone can use. What used to be the hardest part—&quot;how to write code&quot;—is now replaced by the new hardest part: &quot;<strong>What do you want to do?</strong>&quot;</p><blockquote><p><strong>What is Vibe Coding?</strong> Simply put, it&#39;s &quot;programming by speaking.&quot; Vibe coding means you can rely solely on conversing with AI instead of writing code directly to complete a programming project.</p></blockquote><p>Of course, letting AI write code is just the first step. To make a truly usable product, you will still encounter these questions:</p><ul><li>How to let AI write clean, maintainable code?</li><li>How to piece together scattered code into a runnable application?</li><li>How to make the application truly go live and be used by people?</li><li>How to put AI capabilities like text generation and image recognition into your product?</li></ul><p>These questions will find answers in this course.</p><p>Whether you are a student, teacher, doctor, worker, or any common person who knows nothing about technology—you don&#39;t need to learn programming for years first; in two weeks, you can make a runnable, demonstrable product prototype.</p><table tabindex="0"><thead><tr><th>Your Identity</th><th>This Course Can Help You</th></tr></thead><tbody><tr><td>Student</td><td>Assignments, competitions, entrepreneurship; do projects yourself without asking for help</td></tr><tr><td>Professional</td><td>Automate repetitive work, improve efficiency, and even develop side hustles</td></tr><tr><td>Product Manager / Designer</td><td>Ideas no longer stay on paper; quickly make Demos to show bosses/clients</td></tr><tr><td>Entrepreneur / SME Owner</td><td>Validate ideas at low cost; make an MVP without spending tens of thousands on outsourcing</td></tr><tr><td>Teacher / Educator</td><td>Make teaching tools, courseware, and automated questions to improve teaching efficiency</td></tr><tr><td>Doctor / Lawyer / Professional</td><td>Automate professional processes and build your own efficiency tools</td></tr><tr><td>Anyone</td><td>Use AI to solve specific problems in life/work, making the impossible possible</td></tr></tbody></table><p>In the AI era, execution and ideas are always more important than technology.</p><h2 id="growth-path-from-using-ai-to-making-ai-products" tabindex="-1">Growth Path: From &quot;Using AI&quot; to &quot;Making AI Products&quot; <a class="header-anchor" href="#growth-path-from-using-ai-to-making-ai-products" aria-label="Permalink to “Growth Path: From &quot;Using AI&quot; to &quot;Making AI Products&quot;”">​</a></h2><div class="stage-intro"><div class="stage-card"><div class="stage-icon">🎮</div><h3>Getting Started</h3><p class="stage-role">Experience AI Programming</p><div class="stage-tags"><span>Snake Mini-game</span><span>Zero Basics to Start</span><span>Vibe Coding First Experience</span><span>Generate in Minutes</span></div></div></div><div class="stage-grid"><div class="stage-card"><div class="stage-icon">🛠️</div><h3>Stage One</h3><p class="stage-role">Product Manager / Operations</p><div class="stage-tags"><span>AI IDE (Cursor/Claude)</span><span>Requirement Deconstruction &amp; Prototype</span><span>Integrate AI Capabilities</span><span>Full Demo Development</span></div></div><div class="stage-card"><div class="stage-icon">💻</div><h3>Stage Two</h3><p class="stage-role">Junior-Mid Developer / Indie Dev</p><div class="stage-tags"><span>Figma to Code</span><span>Supabase Database</span><span>Stripe Payment Integration</span><span>Dify Knowledge Base</span></div></div><div class="stage-card"><div class="stage-icon">🚀</div><h3>Stage Three</h3><p class="stage-role">Senior Developer / Architect</p><div class="stage-tags"><span>Web/Mini-program/Multi-platform</span><span>MCP Advanced Tools</span><span>RAG &amp; LangGraph</span><span>Senior Engineer Thinking</span></div></div></div><p>Through this complete learning path, you will gain:</p><ul><li><strong>Vibe Coding Development Ability:</strong> Effortlessly use vibe coding thinking and AI coding tools to increase development efficiency several times. No longer need to memorize syntax, but learn how to guide AI to generate high-quality code.</li><li><strong>Full-stack Development Skills:</strong> From UI design to front-end implementation, from database design to API development, and from local development to cloud deployment, master the full technology stack of modern Web applications.</li><li><strong>AI Capability Integration:</strong> Learn to call various multimodal AI APIs and seamlessly integrate AI capabilities like text, images, and voice into your applications, building intelligent products through technologies like RAG.</li><li><strong>Product Thinking and Operations Ability:</strong> From user research to demand deconstruction, from MVP design to product iteration, and from payment integration to user management, form a complete product development and operation closed loop.</li></ul><h1 id="what-can-you-do-after-learning" tabindex="-1">What Can You Do After Learning? <a class="header-anchor" href="#what-can-you-do-after-learning" aria-label="Permalink to “What Can You Do After Learning?”">​</a></h1><h2 id="stage-one-build-your-first-product-prototype" tabindex="-1">Stage One: Build Your First Product Prototype <a class="header-anchor" href="#stage-one-build-your-first-product-prototype" aria-label="Permalink to “Stage One: Build Your First Product Prototype”">​</a></h2><p>This stage is suitable for students with zero programming foundation or those who only know a little but are not confident. You don&#39;t need to learn a lot of theoretical knowledge first, but follow the steps directly and learn how to use AI tools to write code in the process.</p><p><strong>After learning, you can</strong>:</p><ul><li>Independently complete a web application using AI programming tools</li><li>Turn product ideas into clickable, interactive prototypes</li><li>Add AI functions to the prototype (e.g., text-to-image, intelligent dialogue)</li><li>Know how to troubleshoot and solve problems when encountering errors</li></ul><p>Simply put, you can make something &quot;runnable and demonstrable to others.&quot;</p><p>We can first experience AI programming through mini-games, then learn how to use AI programming tools to help you write code and fix errors. Then start from simple pages and gradually make interactive multi-page applications, adding AI functions like text-to-image and intelligent dialogue. Finally, independently complete a full project so that your creativity can truly have the possibility of landing.</p><h1 id="why-use-project-based-training" tabindex="-1">Why Use Project-Based Training? <a class="header-anchor" href="#why-use-project-based-training" aria-label="Permalink to “Why Use Project-Based Training?”">​</a></h1><blockquote><p><strong>Real-world Challenges</strong></p><p>The reason is simple: based on the state of most students now, directly entering the workplace might make it difficult to move an inch under the &quot;social beatings&quot; of real projects and bosses/clients. More common scenarios in the real world are:</p></blockquote><blockquote><p>Your mentor / boss: We want to do xxx, the goal is to achieve yyy effect.</p><p>Documentation? Ready-made frameworks? Detailed requirement specifications? Often they don&#39;t exist.</p></blockquote><p>Many tasks in real work are essentially solving problems never seen before in a highly uncertain environment: requirements are vague, boundaries are changing, no one tells you the standard answer, and you need to look up information, do experiments, build prototypes, iterate continuously, and finally give a &quot;runnable, usable, and launchable&quot; solution.</p><p>What this course wants to do is give you a &quot;simulated social beating&quot; in advance in a relatively safe environment:</p><ul><li>Force you to practice deconstructing problems, designing solutions, and finding information yourself through seemingly difficult project tasks.</li><li>Allow you to learn to read, understand, and transform a medium-to-large codebase through scaffolds and code that are not so &quot;idiot-proof.&quot;</li><li>Let you experience the complete process of a real product from 0 to 1 through the complete closed loop from idea to launch.</li></ul><p>In the short term, this kind of training is indeed torturous; but in the long term, it will greatly improve your competitiveness in job searching and career development: you will be more able to handle things, more able to find breakthroughs in uncertain environments, and more capable of turning AI into real landing products instead of staying in the &quot;playing with demos&quot; stage.</p><h1 id="the-art-of-questioning-an-essential-skill-in-the-ai-era" tabindex="-1">The Art of Questioning: An Essential Skill in the AI Era <a class="header-anchor" href="#the-art-of-questioning-an-essential-skill-in-the-ai-era" aria-label="Permalink to “The Art of Questioning: An Essential Skill in the AI Era”">​</a></h1><p>In the AI era, questioning is also a &quot;basic skill.&quot; For the same code and the same error, <strong>how you ask almost determines what kind of answer AI can give</strong>: whether it&#39;s talking broadly or giving implementable modifications step by step.</p><p><strong>Develop Good Habits</strong>: Treat &quot;asking AI&quot; as part of the daily development flow: ask immediately when you don&#39;t understand or get stuck.</p><h2 id="why-is-this-an-essential-skill" tabindex="-1">Why is this an Essential Skill? <a class="header-anchor" href="#why-is-this-an-essential-skill" aria-label="Permalink to “Why is this an Essential Skill?”">​</a></h2><ul><li><strong>Real life rarely has complete documentation</strong>: Most of the time you face unclear requirements, half-finished code, and scattered error messages.</li><li><strong>AI is your tutor + colleague by your side</strong>: Those who can ask questions can turn it into &quot;high-quality pair programming.&quot;</li><li><strong>Ability upper limit is determined by communication</strong>: The more you can provide key information and the more you can constrain the output format, the more usable the answer will be.</li></ul><p><strong>Common Misconception</strong>: Asking just &quot;Why error?&quot; usually only gets a bunch of guesses. Only by filling in the context will you get an executable solution.</p><h2 id="how-to-feed-information-to-ai-screenshots-vs-copy-paste" tabindex="-1">How to &quot;Feed&quot; Information to AI: Screenshots vs Copy-Paste <a class="header-anchor" href="#how-to-feed-information-to-ai-screenshots-vs-copy-paste" aria-label="Permalink to “How to &quot;Feed&quot; Information to AI: Screenshots vs Copy-Paste”">​</a></h2><p>Both methods are fine, but for different purposes:</p><table tabindex="0"><thead><tr><th>Method</th><th>Applicable Scenarios</th><th>Key Requirements</th></tr></thead><tbody><tr><td><strong>Copy-Paste</strong></td><td>Error stacks, logs, code, configuration, API returns</td><td>Be as complete as possible; don&#39;t just take one line of keywords</td></tr><tr><td><strong>Screenshot</strong></td><td>UI layout issues, interaction anomalies, can&#39;t find buttons in tools</td><td>Screenshot full screen + highlight key areas, preferably with a line of text description</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">⚠️ Important Prerequisite</p><p><strong>Not all AI support image input.</strong> Communication via screenshots requires AI to have multimodal capabilities (i.e., the ability to understand and analyze images). Current AIs that support image input include: Claude (Anthropic), GPT-4V/GPT-4o (OpenAI), Gemini (Google), and some Chinese models like Tongyi Qianwen, Wenxin Yiyan, etc.</p><p><strong>If the AI you are using does not support image input</strong>, screenshots will not be recognized. In this case, please switch to copy-pasting text for communication.</p></div><h2 id="prompt-tips-to-make-ai-explain-well" tabindex="-1">Prompt Tips to Make AI &quot;Explain Well&quot; <a class="header-anchor" href="#prompt-tips-to-make-ai-explain-well" aria-label="Permalink to “Prompt Tips to Make AI &quot;Explain Well&quot;”">​</a></h2><p>If you don&#39;t just want the answer, but want to &quot;learn&quot; the answer. Using instructions like the following can significantly improve the quality of explanation:</p><blockquote><p><strong>Learning Question Examples</strong></p><ul><li>&quot;Please explain this concept clearly in 5 sentences first, and then ask me a few questions to verify if I understood it correctly.&quot;</li><li>&quot;Please explain this error message in detail; I don&#39;t understand why the error occurred.&quot;</li></ul></blockquote><h1 id="i-ve-been-persistent-for-a-long-time-but-still-can-t-handle-it-i-want-to-give-up" tabindex="-1">I&#39;ve been persistent for a long time but still can&#39;t handle it, I want to give up <a class="header-anchor" href="#i-ve-been-persistent-for-a-long-time-but-still-can-t-handle-it-i-want-to-give-up" aria-label="Permalink to “I&#39;ve been persistent for a long time but still can&#39;t handle it, I want to give up”">​</a></h1><p>Maybe your method of persistence is wrong. Don&#39;t hold on alone in the dark; you can come and talk to the authors and teaching assistants: frankly state the methods you have tried, the specific stuck points you encountered, and your current state of mind. Many times, just a slight adjustment in direction or adding a key knowledge point can keep you moving forward.</p><h1 id="i-feel-some-designs-of-the-tutorial-are-unreasonable" tabindex="-1">I feel some designs of the tutorial are unreasonable <a class="header-anchor" href="#i-feel-some-designs-of-the-tutorial-are-unreasonable" aria-label="Permalink to “I feel some designs of the tutorial are unreasonable”">​</a></h1><p>You are welcome to contact the author at any time, submit an issue, or give feedback directly in the group/class. We very much hope to work with you to polish this set of tutorials to be better and better: wherever it&#39;s unclear, wherever the experience is broad, or wherever it makes you waste effort, you can point it out frankly. The more real and specific the feedback, the more it can help newcomers avoid pitfalls.</p><h1 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to “Reference”">​</a></h1><ul><li><a href="https://nju-projectn.github.io/ics-pa-gitbook/ics2025/" target="_blank" rel="noreferrer">Nanjing University Computer Science and Technology Department Computer System Fundamentals Course Experiment</a></li></ul>',50)])])}const g=t(i,[["render",r]]);export{h as __pageData,g as default};
